declare(strict_types=1);require_once dirname(__DIR__) . '/bootstrap.php';require_method('POST');$u=current_user();require_csrf();$d=input();$id=string_value($d,'id',36);$mapping=(array)($d['mapping']??[]);$allowed=['first_name','last_name','full_name','email','company_name','phone','job_title','website','linkedin','facebook','instagram','twitter','tiktok','other_social_links','location','country','source','status','tags','notes'];$clean=[];foreach($mapping as $column=>$field){$field=(string)$field;if(!in_array($field,$allowed,true)&&!preg_match('/^custom:[a-z][a-z0-9_]{0,63}$/',$field))throw new ApiError(422,'Invalid column mapping.');$clean[(string)$column]=$field;}if(!in_array('email',$clean,true)||(!in_array('first_name',$clean,true)&&!in_array('full_name',$clean,true)))throw new ApiError(422,'Map email and either first name or full name.');$s=db()->prepare("UPDATE import_jobs SET column_mapping=?,status='QUEUED' WHERE tenant_id=? AND public_id=? AND created_by=? AND status='UPLOADED'");$s->execute([json_encode($clean,JSON_THROW_ON_ERROR),$u['tenant_id'],$id,$u['id']]);if(!$s->rowCount())throw new ApiError(404,'Import job not found or already started.');audit('import.queued','import_job',$id);respond(['status'=>'QUEUED']);
